/* Colors come exclusively from the semantic tokens applied in tokens.ts. */

/* The product font ships with OrcaSlicer, but it is registered as a private
   font of the native process and WKWebView renders in a separate process
   that cannot see it. A Latin subset is embedded so the Agent page uses the
   same face as the native shell; CJK text falls through to the system font. */
@font-face {
  font-family: 'HarmonyOS Sans SC';
  font-weight: 400;
  font-style: normal;
  src: url('./fonts/HarmonyOS_Sans_SC_Regular_latin.woff') format('woff');
}
@font-face {
  font-family: 'HarmonyOS Sans SC';
  font-weight: 700;
  font-style: normal;
  src: url('./fonts/HarmonyOS_Sans_SC_Bold_latin.woff') format('woff');
}

/* radius/pill from resources/jusprin/ui/design-tokens.json. The other radii on
   the scale (6, 8, 12) are written literally; only the capsule shape needs a
   name, because its value is not a size anyone should read as one. */
:root {
  --radius-pill: 9999px;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
}

body {
  font-family: 'HarmonyOS Sans SC', system-ui, sans-serif;
  font-size: 14px;
  line-height: 20px;
  color: var(--text-primary);
  background: var(--surface-subtle);
  -webkit-user-select: text;
  user-select: text;
}

.app {
  position: relative;
  min-width: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  height: 100%;
}

:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* Compact workspace context header */
.context-summary {
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--surface-canvas);
  font-size: 12px;
  line-height: 16px;
  color: var(--text-secondary);
}

.context-summary .project {
  font-weight: 700;
  color: var(--text-primary);
}

.notice {
  margin: 12px;
  padding: 12px;
  border: 1px solid var(--border-subtle);
  border-radius: 8px;
  background: var(--surface-raised);
}

.notice h2 {
  margin: 0 0 4px;
  font-size: 14px;
  line-height: 20px;
}

.notice p {
  margin: 0;
  color: var(--text-secondary);
  font-size: 12px;
  line-height: 16px;
}

/* Conversation */
.external-actions {
  flex: 0 1 auto;
  min-height: 0;
  max-height: 40%;
  overflow-y: auto;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--surface-canvas);
}
.external-actions h2 { margin: 0 0 8px; font-size: 14px; line-height: 20px; }
.external-actions .tool-card + .tool-card { margin-top: 8px; }

.message-list {
  min-height: 0;
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

/* Chat navigation: the header and configuration footer stay outside the
   scrolling content so both remain reachable in a short or narrow dock. */
.chat-content { display: flex; flex-direction: column; flex: 1; min-height: 0; }
.chat-content[hidden] { display: none; }
.chat-header, .chat-list-header {
  display: flex;
  flex: 0 0 auto;
  align-items: center;
  gap: 8px;
  height: 44px;
  padding: 8px 12px;
  border-bottom: 1px solid var(--border-subtle);
  background: var(--surface-canvas);
}
.chat-header h1, .chat-list-header h1 {
  flex: 1;
  min-width: 0;
  margin: 0;
  overflow: hidden;
  text-overflow: ellipsis;

